// 1. db-service.ts (Server Only - An toàn tuyệt đối)
import 'server-only'; // Ném lỗi build nếu lỡ import vào client!
import { db } from '@/lib/db';

export async function getPrivateUserData(userId: string) {
  return await db.user.findUnique({ where: { id: userId } });
}

// 2. UserProfilePage.tsx (Server Component - 0 KB bundle)
import { getPrivateUserData } from './db-service';
import { ClientAvatarMenu } from './ClientAvatarMenu';

export default async function UserProfilePage({ params }: { params: { id: string } }) {
  const user = await getPrivateUserData(params.id);

  // Dữ liệu truyền xuống ClientAvatarMenu phải serializable!
  return (
    <div>
      <h1>Welcome {user.name}</h1>
      <ClientAvatarMenu user={{ name: user.name, avatarUrl: user.avatarUrl }} />
    </div>
  );
}

// 1. SSG (Static - Build Time)
export const revalidate = false; // Hoặc fetch(url, { cache: 'force-cache' })

// 2. ISR (Incremental - Revalidate ngầm mỗi 60s)
export const revalidate = 60; // Hoặc fetch(url, { next: { revalidate: 60 } })

// 3. SSR (Dynamic - Render mỗi Request)
export const dynamic = 'force-dynamic'; // Hoặc fetch(url, { cache: 'no-store' })

// 4. PPR (Partial Prerendering - Mixed Static Shell + Dynamic Stream)
// next.config.mjs: ppr: 'incremental'
export default function Page() {
  return (
    <div>
      <StaticHeader /> {/* SSG Static Shell */}
      <Suspense fallback={<Skeleton />}>
        <DynamicFeed /> {/* SSR Streamed Content */}
      </Suspense>
    </div>
  );
}
